/** @deprecated legacy window: frozen until client X migrates (v1 wire shape). */
export interface LegacyQuoteV1 {          // the contract, exactly as sent by the client
  readonly SKU: string;
  readonly unit_price: string;            // decimal as text
  readonly ccy?: string;                  // absent means EUR
}
export function fromLegacyV1(dto: LegacyQuoteV1): Quote {
  return { sku: dto.SKU, cents: decimalToCents(dto.unit_price), currency: dto.ccy ?? 'EUR' };
}
export function toLegacyV1(q: Quote): LegacyQuoteV1 {
  return { SKU: q.sku, unit_price: centsToDecimal(q.cents),
           ...(q.currency === 'EUR' ? {} : { ccy: q.currency }) };   // absent, not null
}
